// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address keeper, address vault) public {
        vm.assume(keeper != address(0));
        vm.assume(vault != address(0));
        vm.startPrank(address(0));
        c.pauseDeposit();
        c.unpauseDeposit();
        vm.stopPrank();

        bool isPaused = c.paused();
        assertTrue(!isPaused);
    }
}
